// Retire the previous Chirpy worker for returning visitors.
// Keep this URL available so already registered workers can update to it.
self.addEventListener('install', (event) => {
  event.waitUntil(self.skipWaiting());
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((name) => name.startsWith('chirpy-')).map((name) => caches.delete(name))
      );
      await self.clients.claim();
      await self.registration.unregister();
    })()
  );
});

// No fetch handler: requests go to the network using normal browser caching.
